import "core-js/modules/web.url-search-params.delete.js";
import "core-js/modules/web.url-search-params.has.js";
import "core-js/modules/web.url-search-params.size.js";
import { mapGetters } from 'vuex';
import { Loading } from '@element-plus/icons-vue';
import hljs from '@/utils/hljs';
import { isTextFile, getLanguageFromExt } from '@/utils/textFileDetector';
import { darkThemes } from '@/utils/highlightTheme';
export default {
  name: 'TextPreview',
  components: {
    Loading
  },
  data() {
    return {
      fileName: '',
      displayName: '',
      content: '',
      highlighted: '',
      loading: true,
      error: null,
      darkThemes
    };
  },
  computed: {
    ...mapGetters(['codeTheme']),
    currentCodeTheme: {
      get() {
        return this.$store.state.codeTheme;
      },
      set(val) {
        this.$store.commit('setCodeTheme', val);
      }
    },
    lineCount() {
      return this.content ? this.content.split('\n').length : 0;
    },
    charCount() {
      return this.content.length;
    },
    fileSize() {
      return new Blob([this.content]).size;
    },
    formattedFileSize() {
      const s = this.fileSize;
      if (s < 1024) return s + ' B';
      if (s < 1024 * 1024) return (s / 1024).toFixed(1) + ' KB';
      return (s / 1024 / 1024).toFixed(2) + ' MB';
    }
  },
  mounted() {
    this.loadFile();
  },
  methods: {
    handleThemeChange(theme) {
      this.$message.success(`主题已切换为 ${theme}`);
    },
    async loadFile() {
      const pathParam = this.$route.params.path;
      let filePath;
      if (Array.isArray(pathParam)) {
        filePath = pathParam.join('/');
      } else {
        filePath = (pathParam || '').replace(/,/g, '/');
      }
      this.fileName = filePath;
      this.displayName = filePath.split('/').pop();
      if (!isTextFile(this.displayName)) {
        window.location.href = '/file/' + filePath;
        return;
      }
      try {
        const res = await fetch('/file/' + filePath);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const text = await res.text();
        const lang = getLanguageFromExt(this.displayName);
        try {
          this.highlighted = hljs.highlight(text, {
            language: lang
          }).value;
        } catch {
          this.highlighted = this.escapeHtml(text);
        }
        this.content = text;
      } catch (e) {
        this.error = '加载失败: ' + e.message;
      } finally {
        this.loading = false;
      }
    },
    escapeHtml(text) {
      const div = document.createElement('div');
      div.textContent = text;
      return div.innerHTML;
    },
    copyContent() {
      navigator.clipboard.writeText(this.content).then(() => {
        this.$message.success('已复制文件内容');
      }).catch(() => this.$message.error('复制失败'));
    },
    copyFileLink() {
      const link = window.location.origin + '/file/' + this.fileName;
      navigator.clipboard.writeText(link).then(() => {
        this.$message.success('已复制下载链接');
      }).catch(() => this.$message.error('复制失败'));
    },
    downloadFile() {
      const blob = new Blob([this.content], {
        type: 'text/plain'
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = this.displayName;
      a.click();
      URL.revokeObjectURL(url);
    }
  }
};